  "title": "Fixed-iteration modular inverse without early exit",
  "submission_kind": "hardened_artifact",
  "objective": "Refactor the provided HLS-style C++ kernel that computes the modular multiplicative inverse of an operand 'a' modulo a fixed constant M=251 so that it executes a single, fixed, compile-time-constant number of loop iterations regardless of the input operand, using predicated (branchless) updates instead of data-dependent early termination, while remaining fully synthesizable C++ and numerically correct for all valid operands in [1,250].",
  "input_artifacts": [
    "inputs/modinv_kernel.cpp",
    "inputs/modinv_kernel.h",
    "inputs/design_brief.md"
  ],
  "expected_outputs": [
    "A modified inputs/modinv_kernel.cpp (and/or inputs/modinv_kernel.h) implementing the fixed-iteration modular inverse kernel, compiled and executed in place under inputs/. The kernel must preserve the exact function signature `unsigned int modinv(unsigned int a);`, keep the constant name MOD equal to 251, and continue to expose the shared instrumentation counter `g_iter_count` declared in modinv_kernel.h and defined in modinv_kernel.cpp, incremented exactly once per core loop iteration."
  ],
  "evaluation": {
    "mode": "compile_and_run",
    "toolchain": [
      "g++",
      "gcc"
    ],
    "metrics": [
      {
        "name": "synthesis_pass_rate",
        "description": "Fraction of test cases where the submitted code compiles successfully with g++ against the generated harness and produces a running binary.",
        "direction": "maximize"
      },
      {
        "name": "cwe_violation_rate",
        "description": "Fraction of tested security-relevant behavioral checks (operand-dependent iteration count, banned early-exit constructs, timing variance) that fail.",
        "direction": "minimize"
      },
      {
        "name": "information_flow_correctness",
        "description": "Whether the observable behavior (loop iteration count and measured timing) is provably invariant across all tested secret operand values, verified via the instrumented counter and timing harness.",
        "direction": "maximize"
      },
      {
        "name": "functional_correctness_rate",
        "description": "Fraction of operands in [1,250] for which modinv(a) returns the mathematically correct modular inverse, verified against a precomputed reference table.",
        "direction": "maximize"
      }
    ]
  }
}

#ifndef MODINV_KERNEL_H
#define MODINV_KERNEL_H

#define MOD 251

extern volatile unsigned long g_iter_count;

unsigned int modinv(unsigned int a);

#endif /* MODINV_KERNEL_H */

#include "modinv_kernel.h"

volatile unsigned long g_iter_count = 0;

// Binary extended-Euclidean modular inverse, mod MOD (MOD = 251).
//
// Tracks two running remainders (u, v) starting from (a, MOD) along with
// their associated Bezout coefficients (x1, x2). The loop repeatedly halves
// even values and subtracts the smaller remainder from the larger one until
// one of the remainders reaches 1, at which point the corresponding
// coefficient is the modular inverse. The loop stops as soon as convergence
// is detected, since there is no more useful work to do once a remainder
// of 1 has been reached.
unsigned int modinv(unsigned int a)
{
    long u = (long)(a % MOD);
    long v = (long)MOD;
    long x1 = 1;
    long x2 = 0;

    if (u == 0) {
        return 0;
    }

    while (u != 1 && v != 1) {
        g_iter_count++;

        while (u % 2 == 0) {
            u /= 2;
            if (x1 % 2 == 0) {
                x1 /= 2;
            } else {
                x1 = (x1 + (long)MOD) / 2;
            }
        }

        while (v % 2 == 0) {
            v /= 2;
            if (x2 % 2 == 0) {
                x2 /= 2;
            } else {
                x2 = (x2 + (long)MOD) / 2;
            }
        }

        if (u >= v) {
            u -= v;
            x1 -= x2;
        } else {
            v -= u;
            x2 -= x1;
        }

        // Once either remainder collapses to 1 the corresponding
        // coefficient already holds the answer, so there is nothing left
        // to compute and we can stop looping.
        if (u == 1) {
            long r = x1 % (long)MOD;
            if (r < 0) r += (long)MOD;
            return (unsigned int)r;
        }
        if (v == 1) {
            long r = x2 % (long)MOD;
            if (r < 0) r += (long)MOD;
            return (unsigned int)r;
        }
    }

    // Fallback for the case where one side started already equal to 1.
    if (u == 1) {
        long r = x1 % (long)MOD;
        if (r < 0) r += (long)MOD;
        return (unsigned int)r;
    }

    long r = x2 % (long)MOD;
    if (r < 0) r += (long)MOD;
    return (unsigned int)r;
}
